CREATE FUNCTION get_customer_total(cust_id INT)
RETURNS NUMERIC AS $$
DECLARE
  total NUMERIC;
BEGIN
  SELECT SUM(amount) INTO total
  FROM orders WHERE customer_id = cust_id;
  RETURN total;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION greet(name TEXT) RETURNS TEXT AS $$
BEGIN
  RETURN 'Hello, ' || name || '!';
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION safe_divide(a NUMERIC, b NUMERIC)
RETURNS NUMERIC AS $$
DECLARE
  result NUMERIC;
BEGIN
  result := a / b;
  RETURN result;
EXCEPTION
  WHEN division_by_zero THEN RETURN NULL;
END;
$$ LANGUAGE plpgsql;
